    gap: 12,
  },
  logo: {
    width: 40,
    height: 40,
    borderRadius: 8,
  },
  titleText: {
    color: THEME.text.primary,
    fontSize: 24,
    fontWeight: 'bold',
    fontFamily: Platform.select({ web: 'Cinzel, serif', default: 'System' }),
  },
  controls: {
    flexDirection: 'row',
    gap: 12,
    flexWrap: 'wrap',
  },
  button: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: THEME.primary.accent,
