// Add this component definition before the TokenModal component
const CharacterSheetModal = memo(({ visible, onClose, character, characters, onUpdate, THEME }) => {
  const [editedCharacter, setEditedCharacter] = useState(() => ({
    name: character?.name || '',
    class: character?.class || '',
    level: character?.level || 1,
    owner: character?.owner || '',
    proficiencyBonus: character?.proficiencyBonus || 2,
    abilityScores: character?.abilityScores || {
      STR: 10,
      DEX: 10,
      CON: 10,
      INT: 10,
      WIS: 10,
      CHA: 10
    },
    proficientSkills: character?.proficientSkills || [],
    currency: character?.currency || {
      CP: 0,
      SP: 0,
      EP: 0,
      GP: 0,
      PP: 0
    },
    items: character?.items || [],
    inventory: character?.inventory || []
  }));

  useEffect(() => {
    if (visible && character) {
      setEditedCharacter({
        name: character.name || '',
        class: character.class || '',
        level: character.level || 1,
        owner: character.owner || '',
        proficiencyBonus: character.proficiencyBonus || 2,
        abilityScores: character.abilityScores || {
          STR: 10,
          DEX: 10,
          CON: 10,
          INT: 10,
          WIS: 10,
          CHA: 10
        },
        proficientSkills: character.proficientSkills || [],
        currency: character.currency || {
          CP: 0,
          SP: 0,
          EP: 0,
          GP: 0,
          PP: 0
        },
        items: character.items || [],
        inventory: character.inventory || []
      });
    }
  }, [visible, character]);

  // Add error boundary
  if (!character) {
    console.error('No character data provided to CharacterSheetModal');
    return null;
  }

  const calculateModifier = (score) => {
    return Math.floor((score - 10) / 2);
  };

  const handleAbilityScoreChange = (ability, value) => {
    const newScore = parseInt(value) || 0;
    setEditedCharacter(prev => ({
      ...prev,
      abilityScores: {
        ...prev.abilityScores,
        [ability]: newScore
      }
    }));
  };

  const toggleProficiency = (skill) => {
    setEditedCharacter(prev => ({
      ...prev,
      proficientSkills: prev.proficientSkills.includes(skill)
        ? prev.proficientSkills.filter(s => s !== skill)
        : [...prev.proficientSkills, skill]
    }));
  };

  const getSkillModifier = (skill, ability) => {
    const abilityMod = calculateModifier(editedCharacter.abilityScores[ability]);
    const profBonus = editedCharacter.proficientSkills.includes(skill) ? editedCharacter.proficiencyBonus : 0;
    return abilityMod + profBonus;
  };

  const handleSave = async () => {
    try {
      const updatedCharacter = {
        ...character,
        ...editedCharacter
      };

      onUpdate(updatedCharacter);
    } catch (error) {
      console.error('Error saving character:', error);
      Alert.alert('Error', 'Failed to save character');
    }
  };

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      transparent={true}
      animationType="fade"
      onRequestClose={onClose}
    >
      <View style={modalStyles.overlay}>
        <View style={modalStyles.container}>
          <View style={modalStyles.header}>
            <Text style={modalStyles.title}>
              {character?.name ? 'Edit Character' : 'New Character'}
            </Text>
            <TouchableOpacity 
              style={modalStyles.closeButton}
              onPress={onClose}
            >
              <Text style={modalStyles.closeIcon}>✕</Text>
            </TouchableOpacity>
          </View>

          <ScrollView style={modalStyles.content}>
            {/* Basic Info */}
            <View style={modalStyles.row}>
              <TextInput
                style={modalStyles.input}
                value={editedCharacter.name}
                onChangeText={(text) => setEditedCharacter(prev => ({...prev, name: text}))}
                placeholder="Character Name"
                placeholderTextColor={THEME.text.secondary}
              />
            </View>
            <View style={modalStyles.row}>
              <TextInput
                style={[modalStyles.input, { flex: 1 }]}
                value={editedCharacter.class}
                onChangeText={(text) => setEditedCharacter(prev => ({...prev, class: text}))}
                placeholder="Class"
                placeholderTextColor={THEME.text.secondary}
              />
              <TextInput
                style={[modalStyles.input, { width: 80 }]}
                value={String(editedCharacter.level)}
                onChangeText={(text) => setEditedCharacter(prev => ({...prev, level: parseInt(text) || 1}))}
                placeholder="Level"
                keyboardType="numeric"
                placeholderTextColor={THEME.text.secondary}
              />
            </View>

            {/* Ability Scores */}
            <Text style={modalStyles.title}>Ability Scores</Text>
            <View style={{ 
              flexDirection: 'row', 
              flexWrap: 'wrap', 
              justifyContent: 'space-between',
              backgroundColor: THEME.primary.dark,
              padding: 16,
              borderRadius: 8,
              marginBottom: 20 
            }}>
              {ABILITY_SCORES.map(ability => (
                <View key={ability} style={{ 
                  alignItems: 'center',
                  width: '30%',  // Three columns
                  marginBottom: 16,
                  backgroundColor: THEME.primary.accent,
                  padding: 12,
                  borderRadius: 6,
                }}>
                  <Text style={[modalStyles.label, { 
                    color: THEME.text.primary,
                    fontSize: 16,
                    fontWeight: 'bold',
                    marginBottom: 8
                  }]}>{ability}</Text>
                  <TextInput
                    style={[modalStyles.input, { 
                      textAlign: 'center',
                      width: '100%',
                      height: 40,
                      marginBottom: 4,
                      fontSize: 18
                    }]}
                    value={String(editedCharacter.abilityScores[ability])}
                    onChangeText={(text) => handleAbilityScoreChange(ability, text)}
                    keyboardType="numeric"
                    maxLength={2}
                    selectTextOnFocus={true}
                  />
                  <Text style={{ 
                    color: THEME.secondary.main,
                    fontSize: 14,
                    fontWeight: '600'
                  }}>
                    {calculateModifier(editedCharacter.abilityScores[ability]) >= 0 ? '+' : ''}
                    {calculateModifier(editedCharacter.abilityScores[ability])}
