// Add utility function
const calculateDistance = (pos1, pos2) => {
  const [row1, col1] = pos1.split('-').map(Number);
  const [row2, col2] = pos2.split('-').map(Number);

  // Calculate diagonal distance (D&D 5e uses the larger of the horizontal or vertical distance)
  const horizontal = Math.abs(col1 - col2);
  const vertical = Math.abs(row1 - row2);

  return Math.max(horizontal, vertical) * 5; // Assuming 5ft squares
};

