      }

      const finalRoll = rollType === 'advantage' 
        ? Math.max(...rolls) 
        : rollType === 'disadvantage'
          ? Math.min(...rolls)
          : rolls[0];

      allRolls.push({
        rolls,
        total: finalRoll
      });
    }

    // Calculate grand total including modifier
    const grandTotal = allRolls.reduce((sum, roll) => sum + roll.total, 0) + modifier;

    const newResult = {
      dice: `${diceQuantity}d${sides}`,
      rolls: allRolls.map(r => r.rolls).flat(),
      individualTotals: allRolls.map(r => r.total),
      modifier,
      rollType,
      total: grandTotal,
      timestamp: Date.now()
    };

    setDiceHistory(prev => [newResult, ...prev.slice(0, 49)]);
    Vibration.vibrate(50);
  }, [rollType, modifier, diceQuantity]);

  // Add memoized selectors
  const currentToken = useMemo(() => {
    if (!inCombat || initiative.length === 0) return null;
    const currentInitiative = initiative[currentTurn];
    return tokens[currentInitiative?.position];
  }, [inCombat, initiative, currentTurn, tokens]);

  const activeCharacters = useMemo(() => {
    return characters.filter(char => char.owner === playerName);
  }, [characters, playerName]);

  // Update the handleCellPress function with memoization
  const handleCellPress = useCallback((row, col) => {
    const position = `${row}-${col}`;

    if (tokens[position]) {
      if (isDM || tokens[position].character?.owner === playerName) {
        const newTokens = { ...tokens };
        delete newTokens[position];

        handleAsyncOperation(async () => {
          setTokens(newTokens);
          if (firebaseRef.current) {
            await set(firebaseRef.current, {
              ...initialGameState,
              tokens: newTokens,
              layers,
              initiative,
              inCombat,
              currentTurn
            });
          }
        }, 'Failed to update token');
      }
    } else {
      setSelectedPosition(position);
      setShowCharacterSelectModal(true);
    }
  }, [tokens, playerName, isDM, layers, initiative, inCombat, currentTurn]);

  // Update the savePlayerData function
  const savePlayerData = useCallback(async (updatedCharacters) => {
    if (!playerName || !roomCode) return;

    try {
      // Save to both the room and a separate players collection
      const roomPlayerRef = ref(database, `rooms/${roomCode}/players/${playerName}`);
      const globalPlayerRef = ref(database, `players/${playerName}`);

      const playerData = {
        characters: updatedCharacters,
        lastUpdate: Date.now()
      };

      // Update both locations
      await Promise.all([
        set(roomPlayerRef, playerData),
        set(globalPlayerRef, playerData)
      ]);
    } catch (error) {
      console.error('Error saving player data:', error);
      Alert.alert('Error', 'Failed to save character data');
    }
  }, [playerName, roomCode]);

  // Update the connectToRoom function to use error handling
  const connectToRoom = useCallback(async (code) => {
    if (!code.trim() || !playerName) {
      Alert.alert("Error", "Please enter a room code and player name");
      return;
    }

    await handleAsyncOperation(async () => {
      setIsJoining(true);
      setIsLoading(true);

      // First try to load player's global data
      const globalPlayerRef = ref(database, `players/${playerName}`);
      const playerSnapshot = await get(globalPlayerRef);
      if (playerSnapshot.exists()) {
        const playerData = playerSnapshot.val();
        setCharacters(playerData.characters || []);
      }

      const gameRef = ref(database, `rooms/${code}`);
      firebaseRef.current = gameRef;

      // Check if room exists
      const snapshot = await get(gameRef);
      if (!snapshot.exists()) {
        await set(gameRef, initialGameState);
      }

      // Set up real-time listener with error handling
      const unsubscribe = onValue(gameRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
          setTokens(data.tokens || {});
          setLayers(data.layers || initialGameState.layers);
          setInitiative(data.initiative || []);
          setInCombat(data.inCombat || false);
          setCurrentTurn(data.currentTurn || 0);
          setPartyLoot(data.partyLoot || initialGameState.partyLoot);

          if (data.players && data.players[playerName]) {
            setCharacters(data.players[playerName].characters || []);
          }
        }
      }, (error) => {
        console.error('Firebase error:', error);
        setIsError(true);
        setErrorMessage('Failed to connect to room');
      });

      unsubscribeRef.current = unsubscribe;
      setRoomCode(code);
      setShowRoomModal(false);
      setIsConnected(true);
    }, 'Failed to join room. Please try again.');

    setIsJoining(false);
    setIsLoading(false);
  }, [playerName]);

  // Effects
  useEffect(() => {
    const handleOffline = () => {
      Alert.alert(
        'Connection Lost',
        'Please check your internet connection',
        [{ text: 'OK' }]
      );
    };

    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('offline', handleOffline);
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
      if (firebaseRef.current) {
        off(firebaseRef.current);
      }
    };
  }, []);

  // Move handleMonsterSelection inside the component
  const handleMonsterSelection = useCallback((monster, position) => {
    // Count existing monsters of this type
    const monsterCount = Object.values(tokens)
      .filter(t => t.name.includes(monster.name))
      .length;

    // Create new token
    const newToken = {
      ...monster,
      name: monsterCount > 0 ? `${monster.name} ${monsterCount + 1}` : monster.name,
      color: currentColor,
      isMonster: true,
      effects: []
    };

    // Update tokens
    const newTokens = {
      ...tokens,
      [position]: newToken
    };

    setTokens(newTokens);

    // Update Firebase
    if (firebaseRef.current) {
      set(firebaseRef.current, {
        ...initialGameState,
        tokens: newTokens,
        layers,
        initiative,
        inCombat,
        currentTurn
      });
    }

    setShowCharacterSelectModal(false);
    setSelectedPosition(null);
  }, [tokens, currentColor, layers, initiative, inCombat, currentTurn]);

  // Add to TokenModal component
  const handleHPChange = (amount, isTemp = false) => {
    setSelectedToken(prev => {
      const newHP = Math.max(0, Math.min((prev.hp || 0) + amount, prev.maxHp));
      const newTempHP = isTemp ? Math.max(0, (prev.tempHP || 0) + amount) : (prev.tempHP || 0);

      return {
        ...prev,
        hp: newHP,
        tempHP: newTempHP
      };
    });
  };

  // Add spell slot management to CharacterSheetModal
  const handleSpellSlotChange = (level, type, value) => {
