  // Add condition management
  const addCondition = (tokenId, conditionId, duration) => {
    const newCondition = {
      id: conditionId,
      duration,
      startTime: Date.now(),
      endTrigger: STATUS_EFFECTS.find(e => e.id === conditionId)?.endTrigger
