              await set(roomPlayerRef, {
                characters: newCharacters,
                lastUpdate: Date.now()
              });
            }

            setShowCharacterSheet(false);

          } catch (error) {
            console.error('Error saving character:', error);
            Alert.alert('Error', 'Failed to save character');
          }
