            console.error('Error saving inventory:', error);
            Alert.alert('Error', 'Failed to save inventory');
          }
        }}
      />

      {!isConnected ? (
        <View style={modernStyles.loadingContainer}>
          {isLoading ? (
            <View style={modernStyles.loadingContent}>
              <ActivityIndicator size="large" color={THEME.accent} />
              <Text style={modernStyles.loadingText}>Connecting to room...</Text>
            </View>
          ) : (
            <Text style={modernStyles.loadingText}>Enter a room code to begin</Text>
          )}
        </View>
      ) : (
