          <View style={headerStyles.container}>
            <View style={headerStyles.content}>
              <View style={headerStyles.topBar}>
                <View style={headerStyles.titleContainer}>
                  <Image 
                    source={require('./assets/icon.png')} 
                    style={headerStyles.logo}
