                </View>
                <View style={headerStyles.roomInfo}>
                  <Text style={headerStyles.roomText}>Room: {roomCode}</Text>
                </View>
              </View>

              <ScrollView 
                horizontal={initialIsSmallScreen}
                showsHorizontalScrollIndicator={false}
                contentContainerStyle={headerStyles.controls}
              >
                <TouchableOpacity 
                  style={headerStyles.button}
                  onPress={handleInitiativeRoll}
                >
                  <Text style={headerStyles.buttonIcon}>🎲</Text>
                  <Text style={headerStyles.buttonText}>Roll Initiative</Text>
                </TouchableOpacity>

                {inCombat && (
                  <>
                    <TouchableOpacity
                      style={[headerStyles.button, { backgroundColor: THEME.accent.green }]}
                      onPress={handleNextTurn}
                    >
                      <Text style={headerStyles.buttonIcon}>⮕</Text>
                      <Text style={headerStyles.buttonText}>Next Turn</Text>
                    </TouchableOpacity>

                    <TouchableOpacity
                      style={[headerStyles.button, { backgroundColor: THEME.accent.red }]}
