                >
                  <Text style={headerStyles.buttonIcon}>🚪</Text>
                  <Text style={headerStyles.buttonText}>Leave Room</Text>
                </TouchableOpacity>
              </ScrollView>
            </View>
          </View>

          {/* Main Content */}
          <View style={mainStyles.container}>
            <ScrollView style={mainStyles.content}>
              <View style={mainStyles.contentWrapper}>
                {/* Left Side - Map Tools */}
