                      </TouchableOpacity>

                      {/* Color Selection */}
                      <Text style={[modalStyles.label, { marginTop: 12, marginBottom: 8 }]}>Token Color</Text>
                      <View style={[gridStyles.colorPicker, { backgroundColor: 'transparent', padding: 0 }]}>
                        {COLORS.map(color => (
                          <TouchableOpacity
                            key={color}
                            style={[
                              gridStyles.colorButton,
                              { 
