                                )}
                              >
                                <Text style={diceStyles.toggleText}>Disadvantage</Text>
                              </TouchableOpacity>
                            </View>
                          </View>

                          {/* Quantity and Modifier Controls */}
                          <View style={[diceStyles.controlRow, { justifyContent: 'space-between' }]}>
                            <View style={diceStyles.inputContainer}>
                              <Text style={diceStyles.inputLabel}>Quantity:</Text>
                              <TextInput
                                style={diceStyles.input}
                                value={String(diceQuantity)}
                                onChangeText={text => {
                                  const num = parseInt(text) || 1;
                                  setDiceQuantity(Math.max(1, Math.min(num, 100)));
                                }}
                                keyboardType="numeric"
                                selectTextOnFocus
                              />
                            </View>
                            <View style={diceStyles.inputContainer}>
                              <Text style={diceStyles.inputLabel}>Modifier:</Text>
                              <TextInput
                                style={diceStyles.input}
                                value={String(modifier)}
                                onChangeText={text => {
                                  const num = parseInt(text) || 0;
                                  setModifier(num);
                                }}
                                keyboardType="numeric"
                                selectTextOnFocus
                              />
                            </View>
                          </View>
                        </View>

                        {/* Dice Grid */}
                        <View style={diceStyles.diceGrid}>
                          {DICE_TYPES.map(({ sides, color }) => (
                            <TouchableOpacity
                              key={sides}
                              style={[diceStyles.diceButton, { backgroundColor: color + '20', borderColor: color }]}
                              onPress={() => rollDice(sides)}
                            >
                              <Text style={diceStyles.diceText}>d{sides}</Text>
                            </TouchableOpacity>
                          ))}
                        </View>

                        {/* History */}
                        {diceHistory.length > 0 && (
                          <View style={diceStyles.history}>
                            <Text style={diceStyles.historyTitle}>Roll History</Text>
                            <ScrollView style={diceStyles.historyScroll}>
                              {diceHistory.map((result, index) => (
                                <View key={index} style={diceStyles.historyItem}>
                                  <View style={diceStyles.historyInfo}>
                                    <Text style={diceStyles.historyDice}>
                                      {result.dice}
                                      {result.modifier ? ` + ${result.modifier}` : ''}
                                      {result.rollType !== 'normal' && 
                                        ` (${result.rollType === 'advantage' ? 'Adv' : 'Dis'})`}
                                    </Text>
                                    {result.rolls.length > 1 && (
                                      <Text style={diceStyles.historyRolls}>
                                        Rolls: [{result.rolls.join(', ')}]
                                      </Text>
                                    )}
                                  </View>
                                  <Text style={diceStyles.historyTotal}>{result.total}</Text>
                                </View>
                              ))}
                            </ScrollView>
                          </View>
                        )}
                      </View>
                    </View>
                  </View>

                  {/* Initiative Panel */}
                  {inCombat && (
                    <View style={toolStyles.panel}>
                      <View style={toolStyles.header}>
                        <Text style={toolStyles.title}>Initiative Order</Text>
                        <View style={{ flexDirection: 'row', gap: 8 }}>
                          <TouchableOpacity
                            style={[toolStyles.button, { backgroundColor: THEME.accent.green }]}
                            onPress={handleNextTurn}
                          >
                            <Text style={toolStyles.buttonIcon}>⮕</Text>
                            <Text style={toolStyles.buttonText}>Next Turn</Text>
                          </TouchableOpacity>
                          <TouchableOpacity
                            style={[toolStyles.button, { backgroundColor: THEME.accent.red }]}
                            onPress={handleEndCombat}
                          >
                            <Text style={toolStyles.buttonIcon}>⚔️</Text>
                            <Text style={toolStyles.buttonText}>End Combat</Text>
                          </TouchableOpacity>
                        </View>
                      </View>

                      <View style={toolStyles.content}>
                        <View style={initiativeStyles.list}>
                          {initiative.map((item, index) => (
                            <View
                              key={item.position}
                              style={[
                                initiativeStyles.item,
                                index === currentTurn && initiativeStyles.itemActive,
                                index === initiative.length - 1 && { borderBottomWidth: 0 }
                              ]}
                            >
                              {index === currentTurn && (
                                <View style={initiativeStyles.turnIndicator}>
                                  <Text style={initiativeStyles.turnNumber}>➤</Text>
                                </View>
                              )}
                              <View style={initiativeStyles.itemContent}>
                                <Text style={initiativeStyles.itemName}>
                                  {tokens[item.position]?.name || 'Unknown'}
                                </Text>
                                <Text style={initiativeStyles.itemDetails}>
                                  Initiative: {item.roll}
                                </Text>
                              </View>
                            </View>
                          ))}
                        </View>
                      </View>
                    </View>
                  )}
                </View>
              </View>
            </ScrollView>
          </View>
        </>
      )}
      <Modal
        visible={showDeleteModal}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setShowDeleteModal(false)}
      >
        <View style={modalStyles.overlay}>
          <View style={modalStyles.container}>
            <View style={modalStyles.header}>
              <Text style={modalStyles.title}>Delete Character</Text>
            </View>
            <View style={modalStyles.content}>
              <Text style={modalStyles.label}>
                Type "{characterToDelete?.name}" to confirm deletion
              </Text>
              <TextInput
                style={modalStyles.input}
                value={deleteConfirmText}
                onChangeText={setDeleteConfirmText}
                placeholder="Type character name"
                placeholderTextColor={THEME.text.secondary}
              />
            </View>
            <View style={modalStyles.footer}>
              <TouchableOpacity
                style={[modalStyles.button, { backgroundColor: THEME.primary.accent }]}
                onPress={() => {
                  setShowDeleteModal(false);
                  setDeleteConfirmText('');
                  setCharacterToDelete(null);
                }}
              >
                <Text style={modalStyles.buttonText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[
                  modalStyles.button,
                  { backgroundColor: THEME.accent.red },
                  deleteConfirmText !== characterToDelete?.name && { opacity: 0.5 }
                ]}
                disabled={deleteConfirmText !== characterToDelete?.name}
                onPress={() => {
                  if (deleteConfirmText === characterToDelete?.name) {
                    // Delete logic here
                    const listWithoutChar = characters.filter(c => c.name !== characterToDelete.name);
                    setCharacters(listWithoutChar);

                    // Update Firebase
                    const playerRef = ref(database, `players/${playerName}`);
                    set(playerRef, {
                      characters: listWithoutChar,
                      lastUpdate: Date.now()
                    });

                    if (roomCode) {
                      const roomPlayerRef = ref(database, `rooms/${roomCode}/players/${playerName}`);
                      set(roomPlayerRef, {
                        characters: listWithoutChar,
                        lastUpdate: Date.now()
                      });
                    }

                    setShowDeleteModal(false);
                    setDeleteConfirmText('');
                    setCharacterToDelete(null);
                  }
                }}
              >
                <Text style={modalStyles.buttonText}>Delete</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
      <Modal
        visible={showCharacterSelectModal}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setShowCharacterSelectModal(false)}
      >
        <View style={modalStyles.overlay}>
          <View style={modalStyles.container}>
            <View style={modalStyles.header}>
              <Text style={modalStyles.title}>Select Token Type</Text>
            </View>
            <ScrollView style={modalStyles.content}>
              {isDM && (
                <>
                  <Text style={modalStyles.label}>Place Monster:</Text>
                  <View style={modalStyles.monsterGrid}>
                    {Object.entries(BASIC_MONSTERS).map(([id, monster]) => (
                      <TouchableOpacity
                        key={id}
                        style={[modalStyles.monsterButton, { backgroundColor: THEME.primary.dark }]}
                        onPress={() => handleMonsterSelection(monster, selectedPosition)}
                      >
                        <Text style={modalStyles.monsterName}>{monster.name}</Text>
                        <Text style={modalStyles.monsterStats}>
                          HP: {monster.hp} AC: {monster.ac}
                        </Text>
                        <Text style={modalStyles.monsterType}>
                          CR: {monster.cr} • {monster.type}
                        </Text>
                      </TouchableOpacity>
                    ))}
                  </View>
                </>
              )}

              {/* Character selection section */}
              <Text style={modalStyles.label}>
                {isDM ? 'Or Select Character:' : 'Select Character:'}
              </Text>
              {characters
                .filter(char => char.owner === playerName)
                .map((char, index) => (
                  <TouchableOpacity
                    key={index}
                    style={[
                      modalStyles.button,
                      { marginBottom: 8, backgroundColor: THEME.primary.accent }
                    ]}
                    onPress={() => {
                      // Create token from character
                      const newToken = {
                        name: char.name,
                        color: currentColor,
                        hp: char.hp || 0,
                        maxHp: char.maxHp || 0,
                        ac: char.ac || 0,
                        initiativeBonus: char.initiativeBonus || 0,
                        effects: [],
                        character: char // Store reference to character
                      };

                      const newTokens = {
                        ...tokens,
                        [selectedPosition]: newToken
                      };

                      setTokens(newTokens);

                      // Update Firebase
                      if (firebaseRef.current) {
                        set(firebaseRef.current, {
                          ...initialGameState,
                          tokens: newTokens,
                          layers,
                          initiative,
                          inCombat,
                          currentTurn
                        });
                      }

                      setShowCharacterSelectModal(false);
                      setSelectedPosition(null);
                    }}
                  >
                    <Text style={modalStyles.buttonText}>
                      {char.name} (Level {char.level} {char.class})
                    </Text>
                  </TouchableOpacity>
                ))}

              {/* In the CharacterSelectModal content */}
              {isDM && (
                <>
                  <Text style={[modalStyles.label, { marginBottom: 8 }]}>Place Monster:</Text>
                  <View style={modalStyles.monsterGrid}>
                    {Object.entries(BASIC_MONSTERS).map(([id, monster]) => (
                      <TouchableOpacity
                        key={id}
                        style={[
                          modalStyles.monsterButton,
                          { backgroundColor: THEME.primary.dark }
                        ]}
                        onPress={() => handleMonsterSelection(monster, selectedPosition)}
                      >
                        <Text style={modalStyles.monsterName}>{monster.name}</Text>
                        <Text style={modalStyles.monsterStats}>
                          HP: {monster.hp} AC: {monster.ac}
                        </Text>
                        <Text style={modalStyles.monsterType}>
                          CR: {monster.cr} • {monster.type}
                        </Text>
                      </TouchableOpacity>
                    ))}
                  </View>

                  <Text style={[modalStyles.label, { marginTop: 16, marginBottom: 8 }]}>
                    Or Create Custom Monster:
                  </Text>
                  <TouchableOpacity
                    style={[modalStyles.button, { backgroundColor: THEME.secondary.main }]}
                    onPress={() => {
                      // Show custom monster creation modal
                      setShowCustomMonsterModal(true);
                    }}
                  >
                    <Text style={modalStyles.buttonText}>Create Custom Monster</Text>
                  </TouchableOpacity>

                  <Text style={[modalStyles.label, { marginTop: 16, marginBottom: 8 }]}>
                    Or Place Generic Token:
                  </Text>
                </>
              )}
            </ScrollView>
            <View style={modalStyles.footer}>
              <TouchableOpacity
                style={[modalStyles.button, { backgroundColor: THEME.accent.red }]}
                onPress={() => {
                  setShowCharacterSelectModal(false);
                  setSelectedPosition(null);
                }}
              >
                <Text style={modalStyles.buttonText}>Cancel</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
      <Modal
        visible={showCustomMonsterModal}
        transparent={true}
        animationType="fade"
        onRequestClose={() => setShowCustomMonsterModal(false)}
      >
        <View style={modalStyles.overlay}>
          <View style={modalStyles.container}>
            <View style={modalStyles.header}>
              <Text style={modalStyles.title}>Create Custom Monster</Text>
            </View>
            <ScrollView style={modalStyles.content}>
              <TextInput
                style={modalStyles.input}
                value={customMonster.name}
                onChangeText={(text) => setCustomMonster(prev => ({...prev, name: text}))}
                placeholder="Monster Name"
                placeholderTextColor={THEME.text.secondary}
              />
              <View style={modalStyles.row}>
                <View style={{ flex: 1 }}>
                  <Text style={modalStyles.label}>HP</Text>
                  <TextInput
                    style={modalStyles.input}
                    value={customMonster.hp}
                    onChangeText={(text) => {
                      const hp = parseInt(text) || 0;
                      setCustomMonster(prev => ({...prev, hp, maxHp: hp}));
                    }}
                    keyboardType="numeric"
                    placeholder="Hit Points"
                    placeholderTextColor={THEME.text.secondary}
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={modalStyles.label}>AC</Text>
                  <TextInput
                    style={modalStyles.input}
                    value={customMonster.ac}
                    onChangeText={(text) => setCustomMonster(prev => ({...prev, ac: text}))}
                    keyboardType="numeric"
                    placeholder="Armor Class"
                    placeholderTextColor={THEME.text.secondary}
                  />
                </View>
              </View>
              <View style={modalStyles.row}>
                <View style={{ flex: 1 }}>
                  <Text style={modalStyles.label}>Initiative Bonus</Text>
                  <TextInput
                    style={modalStyles.input}
                    value={customMonster.initiativeBonus}
                    onChangeText={(text) => setCustomMonster(prev => ({...prev, initiativeBonus: text}))}
                    keyboardType="numeric"
                    placeholder="+0"
                    placeholderTextColor={THEME.text.secondary}
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={modalStyles.label}>Challenge Rating</Text>
                  <TextInput
                    style={modalStyles.input}
                    value={customMonster.cr}
                    onChangeText={(text) => setCustomMonster(prev => ({...prev, cr: text}))}
                    placeholder="CR"
                    placeholderTextColor={THEME.text.secondary}
                  />
                </View>
              </View>
              <TextInput
                style={modalStyles.input}
                value={customMonster.type}
                onChangeText={(text) => setCustomMonster(prev => ({...prev, type: text}))}
                placeholder="Monster Type (e.g., Beast, Undead)"
                placeholderTextColor={THEME.text.secondary}
              />
            </ScrollView>
            <View style={modalStyles.footer}>
              <TouchableOpacity
                style={[modalStyles.button, { backgroundColor: THEME.accent.red }]}
                onPress={() => {
                  setShowCustomMonsterModal(false);
                  setCustomMonster({
                    name: '',
                    hp: '',
                    maxHp: '',
                    ac: '',
                    initiativeBonus: '',
                    cr: '',
                    type: ''
                  });
                }}
              >
                <Text style={modalStyles.buttonText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[
                  modalStyles.button,
                  { backgroundColor: THEME.accent.green }
                ]}
                onPress={() => {
                  if (customMonster.name && customMonster.hp) {
                    const newToken = {
                      ...customMonster,
                      color: currentColor,
                      isMonster: true,
                      effects: []
                    };

                    const newTokens = {
                      ...tokens,
                      [selectedPosition]: newToken
                    };

                    setTokens(newTokens);

                    if (firebaseRef.current) {
                      set(firebaseRef.current, {
                        ...initialGameState,
                        tokens: newTokens,
                        layers,
                        initiative,
                        inCombat,
                        currentTurn
                      });
                    }

                    setShowCustomMonsterModal(false);
                    setShowCharacterSelectModal(false);
                    setSelectedPosition(null);
                    setCustomMonster({
                      name: '',
                      hp: '',
                      maxHp: '',
                      ac: '',
                      initiativeBonus: '',
                      cr: '',
                      type: ''
                    });
                  }
                }}
              >
                <Text style={modalStyles.buttonText}>Create & Place</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
      <ErrorFallback error={errorMessage} resetErrorBoundary={() => setIsError(false)} />
      {targetMode && selectedTargets.length > 0 && (
        <Text style={styles.distanceText}>
          Distance: {calculateDistance(selectedPosition, selectedTargets[0])}ft
        </Text>
      )}
      <AoeControls 
        aoeMode={aoeMode}
        selectedAoe={selectedAoe}
        onTypeChange={(type) => setSelectedAoe(prev => ({ ...prev, type }))}
        onSizeChange={(size) => setSelectedAoe(prev => ({ ...prev, size }))}
        onToggle={() => setAoeMode(!aoeMode)}
        styles={styles} // Pass styles as prop
      />
      {/* Add to the tools section in the main render */}
      <View style={toolStyles.panel}>
        <View style={toolStyles.header}>
          <Text style={toolStyles.title}>Area Effects</Text>
        </View>
        <View style={toolStyles.content}>
          <AoeControls
            aoeMode={aoeMode}
            selectedAoe={selectedAoe}
            onTypeChange={(type) => setSelectedAoe(prev => ({
              ...prev,
              type,
              size: AOE_SIZES[type][0]
            }))}
            onSizeChange={(size) => setSelectedAoe(prev => ({
              ...prev,
              size
            }))}
            onToggle={() => {
              setAoeMode(prev => !prev);
              if (aoeMode) {
                setSelectedAoe(prev => ({ ...prev, origin: null }));
              }
            }}
          />
        </View>
      </View>
    </SafeAreaView>
  );
}
